import{_ as i,o as t,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Éthique et limites de la culture","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0019-修炼伦理与边界.md","filePath":"fr/0019-修炼伦理与边界.md"}'),a={name:"fr/0019-修炼伦理与边界.md"};function l(r,e,u,o,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ethique-et-limites-de-la-culture" tabindex="-1">Éthique et limites de la culture <a class="header-anchor" href="#ethique-et-limites-de-la-culture" aria-label="Permalink to &quot;Éthique et limites de la culture&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>19</td></tr><tr><td>Module</td><td>Lois cosmiques et systèmes de culture</td></tr><tr><td>Mots-clés</td><td>Éthique de la culture, Limites, Tabous, Ligne de fond morale, Examen éthique</td></tr></tbody></table><h2 id="i-definition-et-statut-de-l-ethique-de-la-culture" tabindex="-1">I. Définition et statut de l&#39;éthique de la culture <a class="header-anchor" href="#i-definition-et-statut-de-l-ethique-de-la-culture" aria-label="Permalink to &quot;I. Définition et statut de l&#39;éthique de la culture&quot;">​</a></h2><p>L&#39;éthique de la culture est la somme des normes morales et juridiques de la Civilisation Symbiotique de l&#39;Ancre qui régissent le comportement des cultivateurs, délimitent les limites de la culture et maintiennent l&#39;ordre de la culture. À l&#39;ère du prédationisme, la culture était considérée comme un « privilège des forts », et les cultivateurs pouvaient recourir à tous les moyens pour accroître leur puissance — dévorer l&#39;Origine d&#39;autrui, asservir l&#39;âme d&#39;autrui, piller les ressources d&#39;autrui, mener des expériences de culture inhumaines, et ainsi de suite. Cette culture de la « puissance avant tout, éthique nulle » est la racine spirituelle la plus profonde du système prédationniste.</p><p>Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, la construction de l&#39;éthique de la culture a été faite l&#39;une des constructions les plus centrales de la civilisation spirituelle. La proposition centrale de l&#39;éthique de la culture est : « L&#39;acquisition et l&#39;utilisation de la puissance doivent être contraintes par l&#39;éthique. » La civilisation symbiotique considère que la culture n&#39;est pas une affaire purement personnelle, mais une affaire publique impliquant autrui, impliquant la civilisation, impliquant l&#39;ensemble du cosmos. En poursuivant l&#39;élévation de leur propre puissance, les cultivateurs doivent respecter les droits d&#39;autrui, maintenir l&#39;ordre de la civilisation et protéger l&#39;écologie du cosmos. L&#39;éthique de la culture n&#39;est pas une entrave à la culture, mais une gardienne de la culture — elle assure que la culture chemine toujours sur la voie correcte de l&#39;« évolution symbiotique », sans jamais glisser dans l&#39;abîme de la « destruction prédatrice ».</p><p>L&#39;éthique de la culture occupe un statut élevé dans le système juridique de la civilisation symbiotique. La Constitution symbiotique stipule explicitement les principes fondamentaux de l&#39;éthique de la culture ; le Tribunal des Ancres dispose d&#39;un « Tribunal éthique » spécialisé pour juger les affaires d&#39;éthique de la culture ; la certification des niveaux de tous les cultivateurs avancés doit passer par un examen éthique. L&#39;éthique de la culture n&#39;est pas une « contrainte souple » facultative, mais une « norme dure » à force obligatoire.</p><h2 id="ii-principes-fondamentaux-de-l-ethique-de-la-culture" tabindex="-1">II. Principes fondamentaux de l&#39;éthique de la culture <a class="header-anchor" href="#ii-principes-fondamentaux-de-l-ethique-de-la-culture" aria-label="Permalink to &quot;II. Principes fondamentaux de l&#39;éthique de la culture&quot;">​</a></h2><h3 id="_2-1-principe-de-dignite-de-la-vie" tabindex="-1">2.1 Principe de dignité de la vie <a class="header-anchor" href="#_2-1-principe-de-dignite-de-la-vie" aria-label="Permalink to &quot;2.1 Principe de dignité de la vie&quot;">​</a></h3><p>Chaque vie possède une dignité et une valeur inviolables, et aucun comportement de culture ne peut se faire au prix d&#39;une atteinte à la dignité de la vie. Spécifiquement :</p><ul><li>Interdiction d&#39;utiliser d&#39;autres vies comme « matériaux » ou « outils » de la culture</li><li>Interdiction des expériences de culture inhumaines (telles que la vivisection, la torture des âmes, etc.)</li><li>Interdiction d&#39;asservir ou de contrôler le libre arbitre d&#39;autres vies</li><li>Respect du droit de chaque vie à choisir sa propre voie d&#39;évolution, sans forcer autrui à cultiver selon sa propre méthode</li></ul><h3 id="_2-2-principe-antipredation" tabindex="-1">2.2 Principe antiprédation <a class="header-anchor" href="#_2-2-principe-antipredation" aria-label="Permalink to &quot;2.2 Principe antiprédation&quot;">​</a></h3><p>La culture doit reposer sur le fondement de la circulation symbiotique, et ne doit pas utiliser le pillage d&#39;autrui comme moyen. Spécifiquement :</p><ul><li>Interdiction de dévorer ou piller l&#39;Origine, l&#39;énergie ou la fortune d&#39;autres vies</li><li>Interdiction d&#39;accroître sa propre vitesse ou son niveau de culture en nuisant à autrui</li><li>Interdiction de monopoliser les ressources de culture pour des gains indus</li><li>Interdiction d&#39;utiliser « la loi de la jungle » comme excuse pour justifier les comportements prédateurs</li></ul><h3 id="_2-3-principe-de-consentement-eclaire" tabindex="-1">2.3 Principe de consentement éclairé <a class="header-anchor" href="#_2-3-principe-de-consentement-eclaire" aria-label="Permalink to &quot;2.3 Principe de consentement éclairé&quot;">​</a></h3><p>Les comportements de culture impliquant autrui (tels que la transmission maître-disciple, la double culture des partenaires, le partage d&#39;énergie, les expériences de culture, etc.) doivent se dérouler sur la prémiisse que l&#39;autre partie est pleinement informée et consent volontairement. Spécifiquement :</p><ul><li>Expliquer pleinement à l&#39;autre partie le contenu, les risques et les bénéfices du comportement de culture</li><li>Assurer que l&#39;autre partie possède une capacité de jugement autonome complète, sans coercition ni séduction</li><li>L&#39;autre partie a le droit de se retirer à tout moment, sans être forcée de continuer</li><li>Pour les mineurs ou les individus mentalement handicapés, leurs tuteurs exercent le droit de consentement en leur nom sur la base d&#39;une évaluation professionnelle</li></ul><h3 id="_2-4-principe-de-moindre-prejudice" tabindex="-1">2.4 Principe de moindre préjudice <a class="header-anchor" href="#_2-4-principe-de-moindre-prejudice" aria-label="Permalink to &quot;2.4 Principe de moindre préjudice&quot;">​</a></h3><p>Les comportements de culture doivent autant que possible éviter de nuire à autrui et à l&#39;environnement. Lorsqu&#39;un certain impact est inévitable, la méthode la moins nocive doit être choisie, et une compensation raisonnable doit être faite pour le préjudice causé. Spécifiquement :</p><ul><li>Les expériences de culture doivent être prioritairement menées dans l&#39;Espace d&#39;Isolement, empêchant la diffusion des risques</li><li>La culture de combat doit autant que possible se dérouler dans des terrains de culture dédiés, évitant les dommages à l&#39;environnement public</li><li>Les pollutions énergétiques, les dommages spatiaux, etc. générés pendant la culture doivent être nettoyés et réparés en temps utile</li><li>Les activités de culture à haut risque sont interdites dans les zones à forte densité de population</li></ul><h3 id="_2-5-principe-d-honnetete-et-de-non-tromperie" tabindex="-1">2.5 Principe d&#39;honnêteté et de non-tromperie <a class="header-anchor" href="#_2-5-principe-d-honnetete-et-de-non-tromperie" aria-label="Permalink to &quot;2.5 Principe d&#39;honnêteté et de non-tromperie&quot;">​</a></h3><p>Les cultivateurs doivent rester honnêtes dans les affaires liées à la culture, et ne doivent pas commettre de fraude. Spécifiquement :</p><ul><li>Interdiction de falsifier les niveaux de culture, les valeurs de contribution, les résultats d&#39;examens, etc.</li><li>Interdiction de fraude ou de plagiat dans les compréhensions de culture et les résultats de recherche</li><li>Interdiction de fournir des informations fausses dans les demandes de ressources et les déclarations de projets</li><li>Interdiction d&#39;utiliser de fausses promesses pour soutirer les ressources de culture ou la confiance d&#39;autrui</li></ul><h3 id="_2-6-principe-de-responsabilite" tabindex="-1">2.6 Principe de responsabilité <a class="header-anchor" href="#_2-6-principe-de-responsabilite" aria-label="Permalink to &quot;2.6 Principe de responsabilité&quot;">​</a></h3><p>Plus la puissance est grande, plus la responsabilité est grande. Les cultivateurs avancés doivent assumer des responsabilités publiques proportionnées à leur puissance. Spécifiquement :</p><ul><li>Les cultivateurs atteignant un certain niveau ont l&#39;obligation de guider les cultivateurs débutants</li><li>Les cultivateurs avancés ont l&#39;obligation de participer aux affaires publiques telles que la maintenance des ancres et la garde de la civilisation</li><li>Les cultivateurs assument la responsabilité des conséquences de leurs propres comportements de culture, sans s&#39;y soustraire</li><li>Lorsque la civilisation fait face à une crise, les cultivateurs avancés ont l&#39;obligation de se manifester</li></ul><h2 id="iii-tabous-absolus-de-la-culture" tabindex="-1">III. Tabous absolus de la culture <a class="header-anchor" href="#iii-tabous-absolus-de-la-culture" aria-label="Permalink to &quot;III. Tabous absolus de la culture&quot;">​</a></h2><p>Les comportements suivants constituent les « tabous absolus » de la culture ; aucun cultivateur ne peut y toucher en aucune circonstance, et les contrevenants subiront les sanctions les plus sévères :</p><table tabindex="0"><thead><tr><th>Type de tabou</th><th>Comportement spécifique</th><th>Mesures de sanction</th></tr></thead><tbody><tr><td>Pillage de l&#39;Origine</td><td>Dévorer ou piller l&#39;Origine ou le noyau vital d&#39;autres vies</td><td>Abolition de la culture, emprisonnement à vie, annihilation de l&#39;Origine pour les cas graves</td></tr><tr><td>Asservissement des âmes</td><td>Transformer d&#39;autres vies en outils par le contrôle des âmes, l&#39;asservissement spirituel, etc.</td><td>Abolition de la culture, rééducation éthique obligatoire, privation permanente du droit de culture</td></tr><tr><td>Génocide racial</td><td>Massacre ou extermination systématique d&#39;une race à des fins de culture</td><td>Jugement suprême du Tribunal des Ancres, peine capitale</td></tr><tr><td>Destruction de plans</td><td>Détruire un plan entier pour obtenir des ressources ou de la puissance</td><td>Peine capitale, et pleine responsabilité de la restauration du plan</td></tr><tr><td>Expériences inhumaines</td><td>Mener des expériences de culture inhumaines sur des vies intelligentes</td><td>Abolition de la culture, emprisonnement à vie, destruction de tous les résultats de recherche</td></tr><tr><td>Crime temporel</td><td>Utiliser la capacité de retour temporel pour une falsification historique ou un meurtre à grande échelle</td><td>Peine capitale, et privation permanente des capacités liées au temps</td></tr><tr><td>Pollution des lois</td><td>Polluer délibérément les lois originelles du cosmos, causant des dommages irréversibles à l&#39;ensemble du cosmos</td><td>Peine capitale, et purification des lois exécutée par l&#39;organe le plus élevé de la civilisation</td></tr></tbody></table><p>L&#39;établissement des tabous absolus incarne la position ferme de la civilisation symbiotique sur la ligne de fond de l&#39;éthique de la culture. Ces tabous n&#39;ont pas de « zone grise », pas de « circonstances atténuantes » ; tout comportement touchant les tabous absolus subira les sanctions les plus sévères.</p><h2 id="iv-zones-grises-de-l-ethique-de-la-culture-et-principes-de-traitement" tabindex="-1">IV. Zones grises de l&#39;éthique de la culture et principes de traitement <a class="header-anchor" href="#iv-zones-grises-de-l-ethique-de-la-culture-et-principes-de-traitement" aria-label="Permalink to &quot;IV. Zones grises de l&#39;éthique de la culture et principes de traitement&quot;">​</a></h2><p>Outre les interdictions claires, il existe des « zones grises » dans l&#39;éthique de la culture — ces comportements ne sont pas en soi absolument bons ou mauvais ; leur nature éthique dépend de la situation spécifique, du motif, de la méthode et des conséquences. Pour les zones grises, la civilisation symbiotique adopte les principes de traitement suivants :</p><h3 id="_4-1-zones-grises-courantes" tabindex="-1">4.1 Zones grises courantes <a class="header-anchor" href="#_4-1-zones-grises-courantes" aria-label="Permalink to &quot;4.1 Zones grises courantes&quot;">​</a></h3><ul><li><strong>Préjudices dans la culture de combat</strong> : les cultivateurs peuvent se blesser mutuellement dans l&#39;entraînement au combat ; le caractère éthique de ces préjudices dépend de savoir si les deux parties ont donné un consentement éclairé et si le préjudice est dans une plage raisonnable</li><li><strong>Compétition pour les ressources</strong> : le caractère éthique de la compétition entre cultivateurs pour des ressources rares dépend de la loyauté de la méthode de compétition et du respect des règles antimonopoles</li><li><strong>Asymétrie de pouvoir dans les relations maître-disciple</strong> : il existe naturellement une asymétrie de pouvoir entre maître et disciple ; l&#39;abus de pouvoir par le maître nécessite un jugement spécifique</li><li><strong>Prise de risque dans la culture</strong> : certaines méthodes de culture comportent elles-mêmes des risques élevés ; le caractère éthique de la prise de risque volontaire nécessite d&#39;évaluer l&#39;information sur le risque et l&#39;existence d&#39;alternatives</li><li><strong>Coopération de culture interraciale</strong> : la coopération de culture entre différentes races peut impliquer des différences culturelles et des asymétries de pouvoir, nécessitant une évaluation spécifique</li></ul><h3 id="_4-2-principes-de-traitement" tabindex="-1">4.2 Principes de traitement <a class="header-anchor" href="#_4-2-principes-de-traitement" aria-label="Permalink to &quot;4.2 Principes de traitement&quot;">​</a></h3><p>Pour les questions éthiques des zones grises, la civilisation symbiotique adopte le mode de traitement « analyse de situation spécifique + évaluation du comité d&#39;éthique + guidage par précédents » :</p><ol><li><strong>Analyse de situation spécifique</strong> : pas de traitement « uniforme » ; jugement global selon la situation, le motif, la méthode et les conséquences spécifiques</li><li><strong>Évaluation du comité d&#39;éthique</strong> : pour les questions éthiques complexes, soumission au « Comité d&#39;éthique » relevant du Tribunal des Ancres pour évaluation professionnelle</li><li><strong>Guidage par précédents</strong> : les résultats d&#39;évaluation du Comité d&#39;éthique forment des précédents, fournissant un guide pour les affaires similaires ultérieures</li><li><strong>Éducation prioritaire</strong> : pour les comportements inappropriés dans les zones grises, l&#39;éducation et la correction sont prioritaires sur les sanctions sévères directes</li><li><strong>Ajustement dynamique</strong> : avec le développement de la civilisation et l&#39;approfondissement de la compréhension éthique, les critères de jugement des zones grises peuvent être dynamiquement ajustés</li></ol><h2 id="v-education-et-interiorisation-de-l-ethique-de-la-culture" tabindex="-1">V. Éducation et intériorisation de l&#39;éthique de la culture <a class="header-anchor" href="#v-education-et-interiorisation-de-l-ethique-de-la-culture" aria-label="Permalink to &quot;V. Éducation et intériorisation de l&#39;éthique de la culture&quot;">​</a></h2><p>Le maintien de l&#39;éthique de la culture ne peut reposer uniquement sur les sanctions et la supervision externes ; il requiert davantage que les cultivateurs s&#39;y identifient et l&#39;intériorisent au plus profond d&#39;eux-mêmes. La civilisation symbiotique a établi un système d&#39;éducation éthique de la culture systématique :</p><h3 id="_5-1-education-de-base" tabindex="-1">5.1 Éducation de base <a class="header-anchor" href="#_5-1-education-de-base" aria-label="Permalink to &quot;5.1 Éducation de base&quot;">​</a></h3><ul><li>L&#39;éthique de la culture est un cours obligatoire pour tous les cultivateurs ; l&#39;éducation éthique systématique doit commencer dès la Perception de l&#39;Origine</li><li>Le contenu éducatif comprend les principes éthiques, les listes de tabous, l&#39;analyse de cas, la simulation de situations, etc.</li><li>Les méthodes éducatives comprennent l&#39;enseignement en classe, la discussion de cas, les jeux de rôle, l&#39;enseignement par l&#39;exemple des mentors, etc.</li></ul><h3 id="_5-2-education-avancee" tabindex="-1">5.2 Éducation avancée <a class="header-anchor" href="#_5-2-education-avancee" aria-label="Permalink to &quot;5.2 Éducation avancée&quot;">​</a></h3><ul><li>À mesure que les niveaux des cultivateurs s&#39;élèvent, la profondeur et l&#39;ampleur de l&#39;éducation éthique s&#39;élèvent correspondamment</li><li>Les cultivateurs avancés doivent apprendre des questions éthiques plus complexes (telles que l&#39;éthique interplans, l&#39;éthique du temps, l&#39;éthique de la création du monde, etc.)</li><li>Les cultivateurs au-dessus du Dao de l&#39;Origine doivent réussir l&#39;« évaluation éthique avancée » avant de continuer à élever leur niveau</li></ul><h3 id="_5-3-pratique-et-interiorisation" tabindex="-1">5.3 Pratique et intériorisation <a class="header-anchor" href="#_5-3-pratique-et-interiorisation" aria-label="Permalink to &quot;5.3 Pratique et intériorisation&quot;">​</a></h3><ul><li>Encourager les cultivateurs à pratiquer les principes éthiques dans la culture quotidienne, transformant les exigences éthiques en habitudes comportementales conscientes</li><li>Établir le système de sélection des « modèles éthiques », récompensant les cultivateurs aux performances éthiques exceptionnelles</li><li>Les mentors ont l&#39;obligation de transmettre l&#39;esprit éthique tout en enseignant les compétences de culture, réalisant la « transmission conjointe du Dao et de l&#39;art »</li></ul><h2 id="vi-supervision-et-application-de-l-ethique-de-la-culture" tabindex="-1">VI. Supervision et application de l&#39;éthique de la culture <a class="header-anchor" href="#vi-supervision-et-application-de-l-ethique-de-la-culture" aria-label="Permalink to &quot;VI. Supervision et application de l&#39;éthique de la culture&quot;">​</a></h2><h3 id="_6-1-mecanismes-de-supervision" tabindex="-1">6.1 Mécanismes de supervision <a class="header-anchor" href="#_6-1-mecanismes-de-supervision" aria-label="Permalink to &quot;6.1 Mécanismes de supervision&quot;">​</a></h3><ul><li><strong>Surveillance du réseau d&#39;ancres</strong> : le réseau d&#39;ancres surveille en continu les comportements de culture des cultivateurs, fournissant des alertes rapides pour les violations éthiques suspectées</li><li><strong>Système de signalement éthique</strong> : toute vie peut signaler au Tribunal éthique du Tribunal des Ancres les violations de l&#39;éthique de la culture, et les signalants sont protégés</li><li><strong>Évaluation éthique périodique</strong> : les cultivateurs atteignant la Loi de l&#39;Origine et au-dessus doivent subir une évaluation éthique chaque année, les résultats étant consignés dans leur dossier de culture personnel</li><li><strong>Supervision des organisations sociales</strong> : les organisations de cultivateurs, les communautés raciales, etc. sont encouragées à effectuer une supervision interne de l&#39;éthique de la culture de leurs membres</li></ul><h3 id="_6-2-mecanismes-d-application" tabindex="-1">6.2 Mécanismes d&#39;application <a class="header-anchor" href="#_6-2-mecanismes-d-application" aria-label="Permalink to &quot;6.2 Mécanismes d&#39;application&quot;">​</a></h3><ul><li><strong>Tribunal éthique</strong> : le Tribunal des Ancres dispose d&#39;un Tribunal éthique spécialisé chargé de juger les affaires d&#39;éthique de la culture</li><li><strong>Sanctions graduées</strong> : selon la gravité des violations éthiques, des sanctions graduées sont appliquées, de l&#39;avertissement, l&#39;amende, la déduction de valeurs de contribution, la restriction des permissions de culture, l&#39;abolition de la culture, à l&#39;emprisonnement à vie et la peine capitale</li><li><strong>Rééducation éthique</strong> : pour les contrevenants ayant une volonté de repentance, une rééducation éthique peut être menée parallèlement aux sanctions ; après succès, certains droits peuvent être partiellement restaurés</li><li><strong>Antécédents</strong> : les enregistrements de violations de l&#39;éthique de la culture sont consignés en permanence dans le dossier personnel, affectant la certification de niveau, la répartition des ressources, les demandes de postes publics, etc.</li></ul><h2 id="vii-expansion-dynamique-des-limites-de-la-culture" tabindex="-1">VII. Expansion dynamique des limites de la culture <a class="header-anchor" href="#vii-expansion-dynamique-des-limites-de-la-culture" aria-label="Permalink to &quot;VII. Expansion dynamique des limites de la culture&quot;">​</a></h2><p>L&#39;éthique et les limites de la culture ne sont pas des dogmes immuables, mais des normes vivantes dynamiquement ajustées avec le développement de la civilisation, le progrès technologique et l&#39;approfondissement de la compréhension. La civilisation symbiotique a établi un mécanisme d&#39;expansion dynamique des limites de la culture :</p><ol><li><strong>Évaluation éthique des nouvelles technologies</strong> : à chaque émergence d&#39;une nouvelle technologie de culture ou application de loi, une évaluation éthique est d&#39;abord menée ; la promotion n&#39;est autorisée qu&#39;après réussite</li><li><strong>Discussion éthique des nouveaux scénarios</strong> : lorsque la civilisation entre dans de nouveaux stades de développement (comme l&#39;ère interplans, l&#39;ère interstellaire, etc.), des discussions éthiques spéciales sont organisées pour formuler des normes éthiques adaptées aux nouveaux scénarios</li><li><strong>Révision périodique des normes éthiques</strong> : les normes spécifiques de l&#39;éthique de la culture sont révisées tous les cinquante ans, le processus de révision recueillant largement les opinions de toutes les vies</li><li><strong>Accumulation continue des précédents éthiques</strong> : les jugements du Tribunal éthique forment des précédents, enrichissant et précisant continuellement les connotations spécifiques de l&#39;éthique de la culture</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;éthique et les limites de la culture sont le pilier central de la civilisation spirituelle de la Civilisation Symbiotique de l&#39;Ancre. Elles répondent à une question fondamentale : « Quel genre de personne le cultivateur doit-il devenir ? » La réponse de la civilisation symbiotique est : le cultivateur doit devenir une personne ayant de la puissance et, plus encore, de la moralité ; une personne en qui l&#39;évolution personnelle et la symbiose des Dix Mille Races sont unifiées ; une personne qui poursuit la puissance mais n&#39;est absolument jamais asservie par elle. L&#39;éthique de la culture n&#39;est pas une entrave à la puissance, mais une sublimation de la puissance — elle assure que la puissance sert toujours la dignité de la vie et le progrès de la civilisation, et ne devient jamais un outil de destruction et de pillage. Dans un cosmos où la puissance peut déplacer les montagnes et les mers, peut créer des mondes et détruire des mondes, l&#39;éthique de la culture est la dernière et la plus importante ligne de défense gardant la ligne de fond de la civilisation.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Thèses centrales de l&#39;antiprédationisme)</li><li>17-位面至高强者标准 (Normes des experts suprêmes des plans)</li><li>48-司法体系与裁决机制 (Système judiciaire et mécanisme de jugement)</li></ul>',56)])])}const h=i(a,[["render",l]]);export{m as __pageData,h as default};
